const starters=()=>`<div class="starters"><h3>Pick a few goals to start</h3><p>Change them anytime. Weekly ones count twice a week.</p><div class="starter-chips">${STARTERS.map(([id,title,cat,sched,ic])=>`<button type="button" class="starter ${starterPick.has(id)?'on':''}" aria-pressed="${starterPick.has(id)}" data-starter="${id}">${icon(ic)}<span>${esc(title)}</span><small>${sched==='weekly'?'Twice a week':'Every day'}</small></button>`).join('')}</div><div class="starter-actions"><button type="button" class="primary" data-starters-go ${starterPick.size?'':'disabled'}>Start with ${starterPick.size||'these'}</button><button type="button" class="quiet" data-starters-own>Craft my own</button></div></div>`;
async function addStarters(){const today=dayKey();let r=records(),changes={};for(const [id,title,category,schedule,ic]of STARTERS.filter(([id])=>starterPick.has(id))){const g={id:`starter-${id}`,title,category,schedule,target:schedule==='weekly'?2:1,icon:ic,notes:'',steps:[],start:today,archived:false,time:''};Object.assign(changes,goalEditChanges(r,g,{today}));}await Store.setMany(changes);sfx('craftGoal');toast('Your first goals are ready. Check one off to heat the forge.');}
function renderToday(){
 const today=dayKey(),d=selected,future=d>today,label=dayLabel(d);
 const list=planned(d).filter(g=>!['once','monthly','weekly'].includes(g.schedule)&&(scheduledOn(records(),g,d)||g.rescheduledTo));
 const daily=[...list.filter(g=>!g.rescheduledTo),...dayTasks(records(),d,today)],rested=daily.filter(g=>restOnDay(records(),g,d)),active=daily.filter(g=>!restOnDay(records(),g,d)),pending=active.filter(g=>!complete(g,d)&&!notCompletedOnDay(records(),g,d)),done=active.filter(g=>complete(g,d)),missed=active.filter(g=>notCompletedOnDay(records(),g,d)),moved=list.filter(g=>g.rescheduledTo),n=done.length,total=active.length;
 const slide=dayDir?` slide-${dayDir>0?'next':'prev'}`:'';dayDir=0;
 const addLabel=label==='Today'?'today':label==='Tomorrow'?'tomorrow':label;
 const ordered=[...pending,...missed,...rested,...done,...moved];
 const invite=badgePermission()==='default'&&badgeOn()&&(matchMedia('(display-mode: standalone)').matches||navigator.standalone)&&!readFlag('blastforge-badge-invite-v1');
 paint(`${invite?`<section class="panel invite" data-key="badge-invite"><span class="invite-icon">${icon('flag')}</span><div><strong>Show goals left on the app icon?</strong><small>Allow notifications and your home-screen icon shows a number until the day is done.</small></div><div class="invite-actions"><button class="quiet small" data-badge-later>Not now</button><button class="primary small" data-badge-allow>Allow</button></div></section>`:''}${progressStrip()}${horizon()}<section class="panel today-panel"><div class="day-head"><h2 aria-live="polite">${label}</h2><div class="day-meta">${total?`<span class="count-chip">${future?`${total} planned`:`${n}/${total}`}</span>`:''}<span class="small-date">${fmt(d,{weekday:'short',month:'short',day:'numeric'})}</span></div></div>${dayStrip(d)}${future?'':`<div class="daily-progress" aria-label="${n} of ${total} goals crafted"><span style="width:${total?n/total*100:0}%"></span></div>`}<div class="day-body${slide}" data-key="daybody:${d}">${ordered.map(g=>row(g,d)).join('')}${!ordered.length?(goalsOf(records()).length||(ACCOUNT&&!Store.last)?`<div class="empty">Nothing planned${future?' yet':''}.</div>`:starters()):''}<button class="add-day" data-add-day="${d}">${icon('plus')}<span>Add a goal to ${addLabel}</span></button></div></section>${companion()}`);
}
// Liquid glass selector: tap a button, or drag the glass across and let go.
function glassFor(box){let g=box.querySelector(':scope>.glass');if(!g){g=document.createElement('span');g.className='glass';g.setAttribute('aria-hidden','true');g.setAttribute('data-own','');box.prepend(g);}return g;}
function moveGlass(box,btn,{instant=false}={}){if(!box||!btn)return;const g=glassFor(box);if(instant)g.classList.add('no-anim');g.style.width=btn.offsetWidth+'px';g.style.height=btn.offsetHeight+'px';g.dataset.x=btn.offsetLeft;g.dataset.y=btn.offsetTop;g.style.transform=`translate(${btn.offsetLeft}px,${btn.offsetTop}px)`;box.querySelectorAll('button').forEach(b=>b.classList.remove('lit'));if(instant){void g.offsetWidth;g.classList.remove('no-anim');}}
function bindGlass(box,pick){
 if(box._glass)return;box._glass=true;let drag=null;
 const buttons=()=>[...box.querySelectorAll('button')];
 const nearest=x=>buttons().reduce((best,b)=>{const c=b.offsetLeft+b.offsetWidth/2,dist=Math.abs(c-x);return !best||dist<best.dist?{b,dist}:best;},null)?.b;
 const pad=side=>parseFloat(getComputedStyle(box)[side])||0;
 box.addEventListener('pointerdown',e=>{if(e.button>0)return;const g=glassFor(box);drag={x:e.clientX,x0:Number(g.dataset.x||0),y0:Number(g.dataset.y||0),w:g.offsetWidth,id:e.pointerId,moved:false,lastX:e.clientX,lastT:performance.now(),v:0};});
 box.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x;if(!drag.moved){if(Math.abs(dx)<7)return;drag.moved=true;try{box.setPointerCapture(e.pointerId);}catch{}box.classList.add('dragging');}
  const g=glassFor(box),x=Math.max(pad('paddingLeft'),Math.min(box.clientWidth-drag.w-pad('paddingRight'),drag.x0+dx)),t=performance.now();
  drag.v=drag.v*.6+((e.clientX-drag.lastX)/Math.max(1,t-drag.lastT))*.4;drag.lastX=e.clientX;drag.lastT=t;
  const stretch=Math.min(.22,Math.abs(drag.v)*.09);g.dataset.x=x;g.style.transform=`translate(${x}px,${drag.y0}px) scale(${1.06+stretch},${1.1-stretch*.5})`;
  const lit=nearest(x+drag.w/2);buttons().forEach(b=>b.classList.toggle('lit',b===lit));});
 const end=e=>{if(!drag||e.pointerId!==drag.id)return;const was=drag;drag=null;box.classList.remove('dragging');if(!was.moved)return;box._suppress=true;setTimeout(()=>box._suppress=false,60);const g=glassFor(box),b=nearest(Number(g.dataset.x)+was.w/2);moveGlass(box,b);if(b)pick(b);};
 box.addEventListener('pointerup',end);box.addEventListener('pointercancel',end);
 box.addEventListener('click',e=>{if(box._suppress){e.stopPropagation();e.preventDefault();}},true);
}
function setDay(d){const today=dayKey(),last=addDays(today,7);if(d<today)d=today;if(d>last)d=last;if(d===selected)return;dayDir=d>selected?1:-1;selected=d;expanded.clear();render();}
