let migrating=false;
// One fresh start after the practice run (Nathan asked for it): the game resets from Monday 26 October
// 2026 and keeps the dragon's name and color, every goal and all goal history. It runs once, only on a
// synced board whose dragon was adopted during the practice run.
const PRACTICE_END='2026-10-26';
async function endPractice(){const s=game();if(ACCOUNT||s.season||!s.dragon.named||!s.dragon.born||s.dragon.born>PRACTICE_END)return false;if(!Object.entries(records()).some(([k,r])=>k.startsWith('entry:')&&!r.stamp.endsWith(':seed')))return false;await Store.setMany(seasonChanges(s,PRACTICE_END));writeFlag('blastforge-relics-seen-v1',false);try{localStorage.setItem('blastforge-relics-seen-v1','0');localStorage.setItem('blastforge-stage-seen-v1','0');}catch{}return true;}
// A sync that brings nothing new only updates the status line, so the page never repaints for it.
let seenRev=-1,seenRecords=null,syncedOnce=false;
Store.subscribe(()=>{if(Store.status==='Synced'&&!migrating&&!ACCOUNT){migrating=true;Store.migrate().then(done=>{if(done)toast('Cardio & stretch is now part of Grindstone.');return endPractice();}).then(reset=>{if(reset)toast('Fresh start: your dragon kept their name, and today’s goals count toward the new run.');}).catch(()=>{}).finally(()=>{migrating=false;});}const firstSync=Store.status==='Synced'&&!syncedOnce,fresh=firstSync||Store.revision!==seenRev||Store.records!==seenRecords;seenRev=Store.revision;seenRecords=Store.records;if(firstSync)syncedOnce=true;if(!fresh){syncStatus();return;}if(!renderQueued){renderQueued=true;requestAnimationFrame(()=>{renderQueued=false;render();});}});
// The tour walks a new player around the app; after the first-visit welcome it ends at their dragon.
const tour=async(after)=>{const {startTour}=await import('./tour.js?v=16');startTour({go,done:after?()=>go(after):null});};
$('#settings-dialog').addEventListener('click',e=>{if(e.target.closest('[data-tour]')){$('#settings-dialog').close();tour();}});
initGame({Store,toast,render:()=>render(),today:()=>dayKey(),go:next=>go(next),section:()=>section,tour:()=>tour('dragon')});
